  static final List<GrammarRule> _grammarRules = [
    // BEGINNER
    const GrammarRule(id: 1, title: 'Present Simple', titleAr: 'المضارع البسيط', explanation: 'Use for habits and facts. Subject + verb (s/es for he/she/it).', example: 'I study English every day.', level: 'beginner'),
    const GrammarRule(id: 2, title: 'Present Continuous', titleAr: 'المضارع المستمر', explanation: 'Use for actions happening now. Subject + am/is/are + verb-ing.', example: 'I am studying English now.', level: 'beginner'),
    const GrammarRule(id: 3, title: 'Past Simple', titleAr: 'الماضي البسيط', explanation: 'Use for completed actions. Subject + verb-ed (or irregular).', example: 'I studied English yesterday.', level: 'beginner'),
    const GrammarRule(id: 4, title: 'Future Simple (will)', titleAr: 'المستقبل البسيط', explanation: 'Use for predictions and spontaneous decisions. Subject + will + verb.', example: 'I will study English tomorrow.', level: 'beginner'),
    const GrammarRule(id: 5, title: 'Articles (a, an, the)', titleAr: 'أدوات التعريف والتنكير', explanation: 'A/an = indefinite, the = definite. A before consonants, an before vowels.', example: 'A book, an apple, the sun.', level: 'beginner'),
    const GrammarRule(id: 6, title: 'Plural Nouns', titleAr: 'جمع الأسماء', explanation: 'Most nouns: add -s. Ending in s/sh/ch/x: add -es. Irregular: man→men.', example: 'Books, boxes, men, children.', level: 'beginner'),
    const GrammarRule(id: 7, title: 'Possessive Adjectives', titleAr: 'صفات الملكية', explanation: 'my, your, his, her, its, our, their. Come before nouns.', example: 'This is my book.', level: 'beginner'),
    const GrammarRule(id: 8, title: 'Subject Pronouns', titleAr: 'ضمائر الفاعل', explanation: 'I, you, he, she, it, we, they. Replace nouns as subjects.', example: 'She is a teacher.', level: 'beginner'),
    const GrammarRule(id: 9, title: 'Be Verb (am/is/are)', titleAr: 'فعل الكينونة', explanation: 'I am, he/she/it is, you/we/they are. Used for identity and states.', example: 'I am happy. She is smart.', level: 'beginner'),
    const GrammarRule(id: 10, title: 'Can/Cannot', titleAr: 'القدرة والاستحالة', explanation: 'Can + verb for ability. Cannot/can\'t for inability.', example: 'I can swim. I cannot fly.', level: 'beginner'),
    const GrammarRule(id: 11, title: 'Demonstratives', titleAr: 'أسماء الإشارة', explanation: 'This/that (singular), these/those (plural). Near/far.', example: 'This book, those cars.', level: 'beginner'),
    const GrammarRule(id: 12, title: 'Prepositions of Place', titleAr: 'حروف الجر المكانية', explanation: 'in, on, at, under, behind, next to, between.', example: 'The book is on the table.', level: 'beginner'),
    const GrammarRule(id: 13, title: 'Question Words', titleAr: 'كلمات الاستفهام', explanation: 'What, who, where, when, why, how, which.', example: 'Where do you live?', level: 'beginner'),
    const GrammarRule(id: 14, title: 'There is/are', titleAr: 'وجود', explanation: 'There is + singular, There are + plural. For existence.', example: 'There is a cat. There are books.', level: 'beginner'),
    const GrammarRule(id: 15, title: 'Imperatives', titleAr: 'الأمر', explanation: 'Base form of verb for commands/requests. Add please for politeness.', example: 'Open the door. Please sit down.', level: 'beginner'),
    const GrammarRule(id: 16, title: 'Like + Verb-ing', titleAr: 'الإعجاب', explanation: 'Like + gerund for enjoyment. Like + infinitive for preference.', example: 'I like reading. I like to read.', level: 'beginner'),
    const GrammarRule(id: 17, title: 'Have/Has', titleAr: 'الملكية', explanation: 'I/you/we/they have, he/she/it has. For possession.', example: 'I have a car. She has a cat.', level: 'beginner'),
    const GrammarRule(id: 18, title: 'Countable/Uncountable', titleAr: 'قابل العد/غير قابل', explanation: 'Countable: books, cats. Uncountable: water, information.', example: 'A book (countable), water (uncountable).', level: 'beginner'),
    const GrammarRule(id: 19, title: 'Comparatives', titleAr: 'المقارنة', explanation: 'Short adj: -er. Long adj: more + adj. Than for comparison.', example: 'Bigger than, more expensive than.', level: 'beginner'),
    const GrammarRule(id: 20, title: 'Superlatives', titleAr: 'التفضيل', explanation: 'Short adj: -est. Long adj: most + adj. The before superlative.', example: 'The biggest, the most beautiful.', level: 'beginner'),

    // INTERMEDIATE
    const GrammarRule(id: 21, title: 'Present Perfect', titleAr: 'الماضي التام', explanation: 'Have/has + past participle. For experience, unfinished time, recent events.', example: 'I have visited Paris.', level: 'intermediate'),
    const GrammarRule(id: 22, title: 'Past Continuous', titleAr: 'الماضي المستمر', explanation: 'Was/were + verb-ing. For ongoing past actions or background.', example: 'I was studying when she called.', level: 'intermediate'),
    const GrammarRule(id: 23, title: 'Present Perfect Continuous', titleAr: 'الماضي التام المستمر', explanation: 'Have/has been + verb-ing. Duration of an action that started in the past.', example: 'I have been studying for 3 hours.', level: 'intermediate'),
    const GrammarRule(id: 24, title: 'First Conditional', titleAr: 'الشرطية الأولى', explanation: 'If + present simple, will + verb. Real/possible situations.', example: 'If it rains, I will stay home.', level: 'intermediate'),
    const GrammarRule(id: 25, title: 'Second Conditional', titleAr: 'الشرطية الثانية', explanation: 'If + past simple, would + verb. Unreal/hypothetical situations.', example: 'If I had money, I would travel.', level: 'intermediate'),
    const GrammarRule(id: 26, title: 'Third Conditional', titleAr: 'الشرطية الثالثة', explanation: 'If + past perfect, would have + past participle. Regrets about past.', example: 'If I had studied, I would have passed.', level: 'intermediate'),
    const GrammarRule(id: 27, title: 'Passive Voice', titleAr: 'المبني للمجهول', explanation: 'Object + be + past participle (+ by agent). Focus on action, not doer.', example: 'The cake was eaten by the children.', level: 'intermediate'),
    const GrammarRule(id: 28, title: 'Reported Speech', titleAr: 'الكلام المنقول', explanation: 'Shift tenses back. Said/told + (that) + clause.', example: 'She said she was tired.', level: 'intermediate'),
    const GrammarRule(id: 29, title: 'Relative Clauses', titleAr: 'جمل الوصل', explanation: 'Who (people), which (things), that (both), whose (possession).', example: 'The man who lives next door is kind.', level: 'intermediate'),
    const GrammarRule(id: 30, title: 'Gerunds vs Infinitives', titleAr: 'المصدر الفعلي vs المصدر الم不定ي', explanation: 'Some verbs take gerund (enjoy, avoid), some take infinitive (want, decide).', example: 'I enjoy reading. I want to travel.', level: 'intermediate'),
    const GrammarRule(id: 31, title: 'Modal Verbs (must/should/might)', titleAr: 'الأفعال المساعدة', explanation: 'Must (obligation), should (advice), might (possibility), could (ability).', example: 'You must study. You should rest.', level: 'intermediate'),
    const GrammarRule(id: 32, title: 'Phrasal Verbs', titleAr: 'الأفعال المركبة', explanation: 'Verb + preposition/adverb with new meaning. Can be separable or not.', example: 'Give up (quit), look after (care for).', level: 'intermediate'),
    const GrammarRule(id: 33, title: 'Used to / Would', titleAr: 'العادات في الماضي', explanation: 'Used to + verb for past habits. Would + verb also for past habits.', example: 'I used to play football. I would play every day.', level: 'intermediate'),
    const GrammarRule(id: 34, title: 'Quantifiers', titleAr: 'الكميات', explanation: 'Much/many (a lot), few/a few (some), little/a little (some uncountable).', example: 'Many books, much water, few friends.', level: 'intermediate'),
    const GrammarRule(id: 35, title: 'Tag Questions', titleAr: 'أسئلة التأكيد', explanation: 'Positive statement + negative tag, or vice versa. Use auxiliary verb.', example: 'You are a student, aren\'t you?', level: 'intermediate'),
    const GrammarRule(id: 36, title: 'Wish / If only', titleAr: 'التمني', explanation: 'Wish + past simple (present wishes). Wish + past perfect (past regrets).', example: 'I wish I were taller. I wish I had studied.', level: 'intermediate'),
    const GrammarRule(id: 37, title: 'So/Such...that', titleAr: 'درجة', explanation: 'So + adj + that. Such + (a/an) + noun + that. For results.', example: 'It was so hot that I fainted.', level: 'intermediate'),
    const GrammarRule(id: 38, title: 'Verb + Object + Infinitive', titleAr: 'فعل + مفعول به + مصدر', explanation: 'Some verbs take object + to + verb. like, want, ask, tell, advise.', example: 'I want you to come. She told me to wait.', level: 'intermediate'),
    const GrammarRule(id: 39, title: 'Causatives (make/have/get)', titleAr: 'الأفعال السببية', explanation: 'Make + obj + base verb (force). Have + obj + base verb (arrange). Get + obj + to + verb (persuade).', example: 'She made me laugh. I had him call.', level: 'intermediate'),
    const GrammarRule(id: 40, title: 'Future Continuous', titleAr: 'المستقبل المستمر', explanation: 'Will be + verb-ing. Actions in progress at a future time.', example: 'I will be studying at 8 PM.', level: 'intermediate'),
    const GrammarRule(id: 41, title: 'Future Perfect', titleAr: 'المستقبل التام', explanation: 'Will have + past participle. Actions completed before a future time.', example: 'I will have graduated by June.', level: 'intermediate'),
    const GrammarRule(id: 42, title: 'Used to vs Be used to', titleAr: 'العادة vs التعود', explanation: 'Used to = past habit. Be used to + gerund = be accustomed to.', example: 'I used to smoke. I am used to waking early.', level: 'intermediate'),
    const GrammarRule(id: 43, title: 'Cleft Sentences', titleAr: 'جمل التشقير', explanation: 'It is/was + emphasized part + that/who. For emphasis.', example: 'It was John who broke the window.', level: 'intermediate'),
    const GrammarRule(id: 44, title: 'Inversion', titleAr: 'قلب الفاعل والفعل', explanation: 'Negative adverbials at start: Never have I seen... Seldom do we...', example: 'Never have I seen such beauty.', level: 'intermediate'),
    const GrammarRule(id: 45, title: 'Mixed Conditionals', titleAr: 'الشروط المختلطة', explanation: 'Mix past and present conditions. If + past perfect, would + base verb.', example: 'If I had studied medicine, I would be a doctor now.', level: 'intermediate'),
    const GrammarRule(id: 46, title: 'Reduced Relative Clauses', titleAr: 'جمل الوصل المختصرة', explanation: 'Who is/are → being removed. Which was/were → removed.', example: 'The man standing there (= who is standing).', level: 'intermediate'),
    const GrammarRule(id: 47, title: 'Participle Clauses', titleAr: 'جمل PARTICIPLE', explanation: 'Present participle (-ing) for simultaneous actions. Past participle (-ed) for passive.', example: 'Walking home, I saw a cat. Tired, she went to bed.', level: 'intermediate'),
    const GrammarRule(id: 48, title: 'Discourse Markers', titleAr: 'علامات التحويل', explanation: 'However, moreover, furthermore, nevertheless, therefore, consequently.', example: 'It is hard. However, it is possible.', level: 'intermediate'),
    const GrammarRule(id: 49, title: 'Emphatic Structures', titleAr: 'ال structures التأكيدية', explanation: 'Do/does/did + base verb for emphasis. Inversion for emphasis.', example: 'I do like chocolate! Never have I been so happy!', level: 'intermediate'),
    const GrammarRule(id: 50, title: 'Stative Verbs', titleAr: 'الأفعال الحالة', explanation: 'Know, believe, want, like, prefer. Not usually used in continuous.', example: 'I know the answer. (not: I am knowing)', level: 'intermediate'),

    // ADVANCED
    const GrammarRule(id: 51, title: 'Subjunctive Mood', titleAr: 'ال mood التمني', explanation: 'If I were (not was). It is essential that he be... Formal/hypothetical.', example: 'If I were you, I would accept. It is vital that she attend.', level: 'advanced'),
    const GrammarRule(id: 52, title: 'Causative Passives', titleAr: 'المبني للمجهول السببي', explanation: 'Subject + get/have + past participle. Arrange for something to happen.', example: 'I had my car repaired. She got her hair cut.', level: 'advanced'),
    const GrammarRule(id: 53, title: 'Advanced Reported Speech', titleAr: 'الكلام المنقول المتقدم', explanation: 'Reporting verbs: insist, suggest, recommend + that clause (subjunctive).', example: 'He suggested that she study harder.', level: 'advanced'),
    const GrammarRule(id: 54, title: 'Nominalization', titleAr: 'تحويل الأفعال لأسماء', explanation: 'Convert verbs/adj to nouns. Decide → decision, important → importance.', example: 'The decision to leave was hard.', level: 'advanced'),
    const GrammarRule(id: 55, title: 'Advanced Conditionals', titleAr: 'الشروط المتقدمة', explanation: 'Were to + verb (very unlikely). Supposing + gerund. Providing that + clause.', example: 'Were he to resign, chaos would ensue.', level: 'advanced'),
    const GrammarRule(id: 56, title: 'Fronting', titleAr: 'تقديم العناصر', explanation: 'Place adverbials/prepositional phrases at the start for emphasis.', example: 'Never before had she seen such beauty.', level: 'advanced'),
    const GrammarRule(id: 57, title: 'Advanced Passive', titleAr: 'المبني للمجهول المتقدم', explanation: 'Get-passive, have something done, be supposed to. Complex passive forms.', example: 'The plan got cancelled. He is supposed to have left.', level: 'advanced'),
    const GrammarRule(id: 58, title: 'Verb Patterns Advanced', titleAr: 'أنماط الأفعال المتقدمة', explanation: 'Bear + gerund (tolerate). Can\'t help + gerund. It\'s no use + gerund.', example: 'I can\'t help laughing. It\'s no use crying.', level: 'advanced'),
    const GrammarRule(id: 59, title: 'Hedging Language', titleAr: 'اللغة المحجوبة', explanation: 'It seems, it appears, presumably, apparently, it is likely that.', example: 'It seems that he left early.', level: 'advanced'),
    const GrammarRule(id: 60, title: 'Advanced Conjunctions', titleAr: 'حروف الربط المتقدمة', explanation: 'Provided that, in case, lest, whereas, whilst, albeit.', example: 'Provided that you study, you will pass.', level: 'advanced'),
    const GrammarRule(id: 61, title: 'Cleft Sentences Advanced', titleAr: 'جمل التشقير المتقدمة', explanation: 'The thing/person/reason that... What I want is... All I need is...', example: 'What I need is a good rest.', level: 'advanced'),
    const GrammarRule(id: 62, title: 'Advanced Articles', titleAr: 'أدوات التعريف المتقدمة', explanation: 'Zero article with abstract/general nouns. The with unique nouns.', example: 'Life is short. The sun rises in the east.', level: 'advanced'),
    const GrammarRule(id: 63, title: 'Ellipsis', titleAr: 'الحذف', explanation: 'Omit words when meaning is clear. Auxiliary, verb, or object can be omitted.', example: 'Are you coming? Yes, I am (coming).', level: 'advanced'),
    const GrammarRule(id: 64, title: 'Substitution', titleAr: 'الإحلال', explanation: 'Use one/ones/do/does/so to avoid repetition.', example: 'I need a pen. Do you have one?', level: 'advanced'),
    const GrammarRule(id: 65, title: 'Advanced Cohesion', titleAr: 'التماسك المتقدم', explanation: 'Reference, substitution, ellipsis, conjunction, lexical cohesion.', example: 'The experiment failed. This/It proved the theory wrong.', level: 'advanced'),
    const GrammarRule(id: 66, title: 'Formal Register', titleAr: 'السجية الرسمية', explanation: 'Passive voice, nominalizations, complex sentences. Academic writing.', example: 'It was determined that... The investigation revealed...', level: 'advanced'),
    const GrammarRule(id: 67, title: 'Advanced Prepositions', titleAr: 'حروف الجر المتقدمة', explanation: 'On behalf of, in spite of, with regard to, as opposed to, subject to.', example: 'In spite of the rain, we went out.', level: 'advanced'),
    const GrammarRule(id: 68, title: 'Complex Noun Phrases', titleAr: 'العبارات الاسمية المعقدة', explanation: 'Multiple modifiers before/after nouns. Reduced relative clauses.', example: 'The highly sophisticated computer system was updated.', level: 'advanced'),
    const GrammarRule(id: 69, title: 'Information Structure', titleAr: 'هيكلة المعلومات', explanation: 'Given vs new information. Theme vs rheme. Topic vs comment.', example: 'The book (given) was written by a famous author (new).', level: 'advanced'),
    const GrammarRule(id: 70, title: 'Advanced Verb Tenses', titleAr: 'أزمنة الأفعال المتقدمة', explanation: 'Future in the past, past perfect continuous in future, double modals.', example: 'He said he would have been working for 5 hours.', level: 'advanced'),
    const GrammarRule(id: 71, title: 'Conditional Inversion', titleAr: 'قلب شروطي', explanation: 'Had I known (= If I had known). Were I you (= If I were you). Should you need...', example: 'Had I studied harder, I would have passed.', level: 'advanced'),
    const GrammarRule(id: 72, title: 'Advanced Phrasal Verbs', titleAr: 'الأفعال المركبة المتقدمة', explanation: 'Three-part phrasal verbs. Get away with, put up with, look forward to.', example: 'I look forward to meeting you.', level: 'advanced'),
    const GrammarRule(id: 73, title: 'Advanced Modals', titleAr: 'الأفعال المساعدة المتقدمة', explanation: 'Must have + pp (deduction), should have + pp (regret), could have + pp (possibility).', example: 'He must have left. I should have studied.', level: 'advanced'),
    const GrammarRule(id: 74, title: 'Concession', titleAr: 'التنازل', explanation: 'Although, even though, despite, in spite of, however, nevertheless.', example: 'Although it was raining, we played football.', level: 'advanced'),
    const GrammarRule(id: 75, title: 'Advanced Connectors', titleAr: 'الروابط المتقدمة', explanation: 'Not only...but also, not only...but...as well, neither...nor, either...or.', example: 'Not only did he win, but he also broke the record.', level: 'advanced'),
    const GrammarRule(id: 76, title: 'Academic Writing', titleAr: 'الكتابة الأكاديمية', explanation: 'Thesis statement, topic sentences, supporting evidence, conclusion.', example: 'This paper argues that... The evidence suggests...', level: 'advanced'),
    const GrammarRule(id: 77, title: 'Argument Structures', titleAr: 'هياكل الحجاج', explanation: 'Claim, evidence, reasoning, counterargument, rebuttal.', example: 'The claim is that... Evidence supports this because...', level: 'advanced'),
    const GrammarRule(id: 78, title: 'Pragmatic Competence', titleAr: 'الكفاءة التداولية', explanation: 'Understanding implied meaning, politeness strategies, indirect speech acts.', example: 'Could you pass the salt? (request, not question)', level: 'advanced'),
    const GrammarRule(id: 79, title: 'Advanced Cohesive Devices', titleAr: 'الأدوات التماسكية المتقدمة', explanation: 'Lexical chains, collocations, idiomatic expressions.', example: 'The research was groundbreaking. It opened up new avenues.', level: 'advanced'),
    const GrammarRule(id: 80, title: 'Register and Style', titleAr: 'السجية والأسلوب', explanation: 'Formal vs informal. Technical vs general. Literary vs colloquial.', example: 'Formal: commence. Informal: start. Technical: utilize. General: use.', level: 'advanced'),
    const GrammarRule(id: 81, title: 'Sentence Variety', titleAr: 'تنويع الجمل', explanation: 'Simple, compound, complex, compound-complex sentences.', example: 'Simple: I went. Complex: When I arrived, they left.', level: 'advanced'),
    const GrammarRule(id: 82, title: 'Rhetorical Devices', titleAr: 'الأجهزة البلاغية', explanation: 'Anaphora, antithesis, chiasmus, parallelism, tricolon.', example: 'Government of the people, by the people, for the people.', level: 'advanced'),
    const GrammarRule(id: 83, title: 'Advanced Punctuation', titleAr: 'علامات الترقيم المتقدمة', explanation: 'Semicolons, colons, dashes, parentheses, em-dashes.', example: 'I have one goal: to succeed. Use semicolons; for related clauses.', level: 'advanced'),
    const GrammarRule(id: 84, title: 'Paraphrasing', titleAr: 'إعادة الصياغة', explanation: 'Restate ideas in different words. Use synonyms and different structures.', example: 'Original: He is smart. Paraphrased: He is intelligent.', level: 'advanced'),
    const GrammarRule(id: 85, title: 'Summarizing', titleAr: 'التلخيص', explanation: 'Condense main points. Use reporting language. Be concise.', example: 'In summary, the study found that...', level: 'advanced'),
    const GrammarRule(id: 86, title: 'Synthesizing Sources', titleAr: 'مزج المصادر', explanation: 'Combine multiple sources. Show agreement/disagreement. Create new meaning.', example: 'Smith (2020) and Jones (2021) both argue that...', level: 'advanced'),
    const GrammarRule(id: 87, title: 'Critical Analysis', titleAr: 'التحليل النقدي', explanation: 'Evaluate arguments, identify assumptions, assess evidence.', example: 'While the study is well-designed, it fails to account for...', level: 'advanced'),
    const GrammarRule(id: 88, title: 'Advanced Coherence', titleAr: 'التماسك المتقدم', explanation: 'Logical flow, paragraph transitions, thematic progression.', example: 'Furthermore, this leads to... In contrast, the opposite...', level: 'advanced'),
    const GrammarRule(id: 89, title: 'Advanced Academic Phrases', titleAr: 'عبارات أكاديمية متقدمة', explanation: 'It is worth noting that, it is imperative to, there is a growing consensus.', example: 'It is worth noting that recent studies suggest...', level: 'advanced'),
    const GrammarRule(id: 90, title: 'Error Correction', titleAr: 'تصحيح الأخطاء', explanation: 'Common errors: subject-verb agreement, tense consistency, run-on sentences.', example: 'Wrong: He don\'t know. Right: He doesn\'t know.', level: 'advanced'),
    const GrammarRule(id: 91, title: 'Advanced Grammar Review', titleAr: 'مراجعة نحوية متقدمة', explanation: 'Comprehensive review of all grammar points with advanced applications.', example: 'Master all tenses, conditionals, and advanced structures.', level: 'advanced'),
    const GrammarRule(id: 92, title: 'Idiomatic Grammar', titleAr: 'النحو الاصطلاحي', explanation: 'Grammar structures that appear in idioms. Had better, would rather, etc.', example: 'You had better study. I would rather stay home.', level: 'advanced'),
    const GrammarRule(id: 93, title: 'Advanced Sentence Types', titleAr: 'أنواع الجمل المتقدمة', explanation: 'Declarative, interrogative, imperative, exclamatory, optative.', example: 'Optative: Long live the king! Exclamatory: What a day!', level: 'advanced'),
    const GrammarRule(id: 94, title: 'Grammar in Context', titleAr: 'النحو في السياق', explanation: 'Understanding how grammar functions in real communication.', example: 'Grammar is not just rules; it is a system of meaning.', level: 'advanced'),
